body.code:
POST {base}/v1/decide     Authorization: Bearer curva_…    Content-Type: application/json
  {"state": <any JSON>, "questions": {<key>: <question>}, "project": "…"}
→ {"id": "dec_…", "answers": {<key>: {"choice" | "score" | "noul" | "selected", "confidence", "abstain", …}}}
POST {base}/v1/feedback   {"decision_id": "dec_…", "question": <key>, "label": <true answer>}

curl -s localhost:7777/v1/decide -H 'content-type: application/json' -d '{
  "state": {"ticket": "The app crashes on launch"},
  "questions": {"team": {"type": "choice", "instructions": "Which team?",
                         "options": {"billing": "", "technical": ""}}}
}'

body.chart:
flowchart TD
  R["POST /v1/decide response"] --> A{"abstain is true?"}
  A -- yes --> H["human review"]
  A -- no --> C{"choice"}
  C -- "none_of_these" --> H
  C -- "an option key" --> O["that route"]
  R --> N{"noul above your threshold?"}
  N -- yes --> Y["yes branch"]
  N -- no --> X["no branch"]
